// Файл згенеровано scripts/build_kz_akafisty.py. Абзац з префіксом § — рубрика, з префіксом # — підзаголовок.
import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст Чесному і Животворящому Хресту Господньому (нова редакція)","e":"Akathist to the Precious and Life-giving Cross of the Lord (new redaction)","secs":[{"h":"Кондак 1","ps":["О всеспаси́тельний Кре́сте і всечестни́й, тебі́ покланя́ємся ві́рнії і велича́єм, ра́дующеся боже́ственному твоєму́ воздви́женію: но я́ко побі́ди зна́меніє і ору́жіє непреобори́моє, огради́ і покри́й твоє́ю благода́тію тебі́ вопію́щия:","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Ікос 1","ps":["А́нгели с небесе́ неви́димо окружа́ють Крест живоно́сний в стра́сі, і светопода́тельную благода́ть оби́льно подаю́ща ни́ні ві́рним ви́дяще, ужаса́ються і стоя́ть вопію́ще к нему́ сицева́я:","Ра́дуйся, Кре́сте, вселе́нния храни́телю;","ра́дуйся, Це́ркве прославле́ніє.","Ра́дуйся, ісціле́нія ізоби́льно істоча́яй;","ра́дуйся, преді́ли ми́ра просвіща́яй.","Ра́дуйся, дре́во живоблагоуха́нноє і чуде́с сокро́вище;","ра́дуйся, пречу́дний благода́тей пода́телю.","Ра́дуйся, я́ко єси́ подно́жіє боже́ственноє;","ра́дуйся, я́ко положе́н бил єси́ всім на поклоне́ніє.","Ра́дуйся, ча́ше, некта́ра іспо́лненная;","ра́дуйся, світи́льниче го́рнія сві́тлости.","Ра́дуйся, і́мже вся твар благословля́ється;","ра́дуйся, і́мже поклоне́ніє Творцю́ возсила́ється.","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 2","ps":["Ви́дящи Єле́на в себі́ жела́ніє обрісти́ Крест, глаго́леть царе́ві дерзнове́нно: всевожделе́нноє душі́ твоє́й удо́бнійше моєму́ тща́нію явля́ється: і́щущи у́бо держа́внійшеє ті побі́ди зна́меніє, я́ко глаго́леши, зову́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум неразумева́ємий пре́жде цари́ця разумі́вши, а́біє возопи́ к служи́телем: із боку́ землі́ ізвлещи́ вско́рі і пода́ти Крест потщі́теся, на него́же воззрі́вши рече́ в стра́сі, оба́че зову́щи си́це:","Ра́дуйся, ра́дости і́стинния зна́меніє;","ра́дуйся, кля́тви дре́внія іскупле́ніє.","Ра́дуйся, сокро́вище, в землі́ за́вистію сокрива́ємоє;","ра́дуйся, явле́йся звізда́ми вообража́ємий.","Ра́дуйся, Кре́сте четверолучео́гненний і огнеобра́зний;","ра́дуйся, лі́ствице високоутвержде́нная, дре́вле предуви́денная.","Ра́дуйся, а́нгелов тихообра́зноє чу́до;","ра́дуйся, де́монов многоплаче́вная я́зво.","Ра́дуйся, кра́сноє сло́ва сокро́вище;","ра́дуйся, пла́мене пре́лести угаше́ніє.","Ра́дуйся, предста́телю неіму́щих;","ра́дуйся, тве́рдий наста́вниче благотеку́щих.","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 3","ps":["Си́ла дре́ва кре́стнаго яви́ся тогда́ ко увіре́нію і́стинному всіх, і безгла́сную і ме́ртвую к животу́ возста́ви, і се бисть тогда́ стра́шноє виді́ніє всім іме́ющим жа́ти спасе́ніє, во є́же пі́ти си́це: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи Єле́на ору́жіє непобіди́моє, востече́ к си́ну своєму́, той же а́біє возра́довася премно́го, позна́в Крест пресла́вний, і во весе́лії душе́внім вопія́ше к нему́ сицева́я:","Ра́дуйся, Кре́сте, сві́та прия́телище;","ра́дуйся, Кре́сте, жи́зні сокро́вище.","Ра́дуйся, дарова́ній духо́вних пода́телю;","ра́дуйся, морепла́вателем необурева́ємоє приста́нище.","Ра́дуйся, трапе́зо, я́ко же́ртву нося́щая Христа́;","ра́дуйся, розго́, грозд іму́щая, вино́ та́їнственноє істоча́ющий.","Ра́дуйся, я́ко ски́птри царе́й охраня́єши;","ра́дуйся, я́ко глави́ зміє́в сокруша́єши.","Ра́дуйся, сві́тлоє ві́ри зна́меніє;","ра́дуйся, всего́ ми́ра ізбавле́ніє.","Ра́дуйся, сме́ртним Бо́жиє благослове́ніє;","ра́дуйся, к Бо́гу о сме́ртних хода́тайство.","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 4","ps":["Ре́вность внутр боже́ственную Єле́на приє́мши, взиська́ і обрі́те со тща́нієм в землі́ Крест сокрива́ємий, і яви́вшийся на небесі́ царе́ві, єго́же возви́си, і ви́дівше лю́діє ві́рою реко́ша: Аллилу́я."]},{"h":"Ікос 4","ps":["Солнцезра́чен яви́ся Крест в ми́рі, і всі просвіще́нія іспо́лньшеся і прите́кше я́ко ко звізді́, зрять сего́, я́коже до́брих вину́, рука́ма освяще́ннима воздви́жена, єго́же пою́ще рі́ша:","Ра́дуйся, заре́ ми́сленнаго со́лнця;","ра́дуйся, істо́чниче неістощи́маго ми́ра.","Ра́дуйся, Ада́ма і Є́ви воззва́ніє;","ра́дуйся, князе́й а́дових умерщвле́ніє.","Ра́дуйся, я́ко воздвиза́ємий ни́ні нас совоздвиза́єши;","ра́дуйся, я́ко покланя́ємий ду́ші на́ша освяща́єши.","Ра́дуйся, апо́столов ми́ру пропове́данная сла́во;","ра́дуйся, страстоте́рпцев благода́тнійшая крі́посте.","Ра́дуйся, Кре́сте, неві́рних обличе́ніє;","ра́дуйся, ві́рних челові́ков похвало́.","Ра́дуйся, і́мже низве́ржеся ад;","ра́дуйся, і́мже возсія́ благода́ть.","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 5","ps":["Богодарова́нноє дре́во уви́дівше, всі да прибі́гнем ни́ні к покро́ву єго́, держа́ще сіє́ я́ко ору́жіє, обрати́м в бі́гство полки́ враго́в, і косну́вшеся устна́ми подно́жія Неприкоснове́ннаго, воззове́м Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́ді світ с небесе́ Константи́н Вели́кий, показу́ющий Креста́ зна́меніє звізда́ми, і́мже і побіжда́я враго́в мно́жество, потща́ся Дре́во яви́ти і возопи́ти к нему́ сицева́я:","Ра́дуйся, неізрече́ннаго сові́та ісполне́ніє;","ра́дуйся, рог люде́й благочести́вих.","Ра́дуйся, полки́ враго́во в бі́гство обраща́яй;","ра́дуйся, де́мони я́ко пла́м'я сожига́яй.","Ра́дуйся, небе́сний ски́птре ві́рнаго царя́;","ра́дуйся, непобіди́мая побі́до христолюби́ваго во́їнства.","Ра́дуйся, горди́ню вра́жию ниспроверга́яй;","ра́дуйся, о душа́х челові́чеських попече́ніє прилага́яй.","Ра́дуйся, от мно́гих зол защище́ніє;","ра́дуйся, вели́ких благ награжде́ніє.","Ра́дуйся, і́мже христоно́сці взигра́ють;","ра́дуйся, і́мже распина́теліє рида́ють.","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 6","ps":["Лі́ствиця, до небе́с досяза́ющая, Крест Госпо́день бисть, вся возводя́ от землі́ к висоті́ небе́сній, с ли́ки а́нгельськими сообита́ти всегда́, оста́вльшія ни́ні су́щая я́ко не су́щая, і ве́дущия пі́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́в світ всім, Спа́се, су́щим во а́ді, просвіти́л єси́ до́лу лежа́щия: вра́тници же а́дови, зари́ не терп'я́ще твоєя́, я́ко ме́ртви падо́ша. Ізба́вльшіїся же сих, ни́ні зря́ще Крест вопію́ть:","Ра́дуйся, уме́рших воскресе́ніє;","ра́дуйся, пла́чущих утіше́ніє.","Ра́дуйся, а́дових храни́лищ істоще́ніє;","ра́дуйся, ра́йськія сла́дости вкуше́ніє.","Ра́дуйся, же́зле, во́їнство єги́петськоє потопи́вий;","ра́дуйся, па́ки ізра́їльськия лю́ди напоі́вий.","Ра́дуйся, одушевле́нноє дре́во, разбо́йника спасе́ніє;","ра́дуйся, ши́пок благово́нний, благочести́вих благоуха́ніє.","Ра́дуйся, пи́ще а́лчущих духо́вно;","ра́дуйся, печа́те, ю́же прия́ша челові́ци.","Ра́дуйся, Кре́сте, та́їнств отверзе́ніє.","Ра́дуйся, істоча́яй боже́ственния струї́.","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 7","ps":["Хотя́щу Моїсе́йові ізба́вити лю́ди многострада́льния от гони́теля, дан бил єси́ єму́ я́ко жезл, но позна́лся от него́ я́коже Бо́жиє зна́меніє, сего́ ра́ди ізумле́н бисть той могу́ществом Креста́ Госпо́дня і возопи́: Аллилу́я."]},{"h":"Ікос 7","ps":["Зако́н да́вий іногда́ богови́дцю на Сина́ї, пригвожде́н бисть во́лею ко Кресту́ за лю́ди беззако́нния, і упраздни́ зако́на кля́тву дре́внюю, да всі ми, ви́дяще ни́ні Креста́ си́лу, воззове́м єму́:","Ра́дуйся, па́дших челові́ков воста́ніє;","ра́дуйся, ми́ру сему́ покланя́ющихся паде́ніє.","Ра́дуйся, воскресе́нія Христо́ва прославле́ніє;","ра́дуйся, мона́шествующих боже́ственноє услажде́ніє.","Ра́дуйся, дре́во благосінноли́ственноє, і́мже покрива́ються ві́рнії;","ра́дуйся, дре́во, проро́ки глаго́ланноє, на землі́ насажде́нноє.","Ра́дуйся, ца́рствію на враги́ поможе́ніє;","ра́дуйся, христоімени́тому жи́тельству держа́вноє предста́тельство.","Ра́дуйся, Судії́ Пра́веднаго явле́ніє;","ра́дуйся, челові́ков согріша́ющих осужде́ніє.","Ра́дуйся, Кре́сте, сиро́т засту́пниче;","ра́дуйся, Кре́сте, ни́щих богати́телю.","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до ви́дівше, стра́нноє житіє́ поживе́м, ум на не́бо возвиша́юще: сего́ бо ра́ди на Кресті́ Христо́с пригвозди́ся і пло́тію пострада́, хотя́ привлещи́ к висоті́ Єму́ вопію́щия: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь приї́де с висоти́, Бог сий, єди́ноє предві́чноє Сло́во, і рожде́йся от Ді́ви Ма́тере, і явле́йся ми́рові смире́н Челові́к, Крест восприє́мий, оживи́ єму́ вопію́щия:","Ра́дуйся, Кре́сте, ору́жіє ми́ра;","ра́дуйся, путеше́ствующим огражде́ніє.","Ра́дуйся, спаса́ющимся прему́дрость і утвержде́ніє;","ра́дуйся, погиба́ющим безу́міє і сокруше́ніє.","Ра́дуйся, благопло́дноє, безсме́ртноє і живоно́сноє проізрасте́ніє;","ра́дуйся, цві́те, процві́тшій на́ше спасе́ніє.","Ра́дуйся, я́ко су́щая на землі́ с го́рніми соєдиня́єши;","ра́дуйся, я́ко сердца́ до́льних просвіща́єши.","Ра́дуйся, і́мже тлі́ніє ізгна́ся;","ра́дуйся, і́мже печа́ль ісчезе́.","Ра́дуйся, неізмери́моє блаже́нство до́брих;","ра́дуйся, многоіме́нная сла́во ві́рних.","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 9","ps":["Паде́ де́монов всескве́рний полк, і род распина́телей устиді́ся, ви́дяще ни́ні Крест от всіх с любо́вію покланя́ємий, при́сно же істоча́ющий ісціле́нія вопію́щим: Аллилу́я."]},{"h":"Ікос 9","ps":["Пото́ци преста́ша помишле́ній злосла́вних, распе́ншуся ті, Христе́, на дре́ві: недоуміва́ють бо, є́же ка́ко і Крест претерпі́л єси́, і тлі́нія ізбіжа́л єси́. Ми же воскресе́ніє сла́в'яще возопії́м:","Ра́дуйся, прему́дрости Бо́жия висото́;","ра́дуйся, промишле́нія єго́ глубино́.","Ра́дуйся, безу́мним суєсло́вцем неве́домий;","ра́дуйся, неразу́мних прориця́телей погубле́ніє.","Ра́дуйся, я́ко воскресе́ніє Христо́во явля́єши;","ра́дуйся, я́ко страда́нія Єго́ обновля́єши.","Ра́дуйся, преступле́ніє первозда́нних разріши́вий;","ра́дуйся, рая́ вхо́ди отве́рзий.","Ра́дуйся, Кре́сте, всі́ми почита́ємий;","ра́дуйся, язи́ком неві́рним сопроти́вниче.","Ра́дуйся, Кре́сте, неду́гующим врачу́;","ра́дуйся, при́сний вопію́щим помо́щниче.","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, і́же ми́ра Украси́тель, сни́де к нему́ неізрече́нно, і Крест претерпі́, Бог сий: нас ра́ди вся я́же по нам приє́млеть, ті́мже і ізбавле́й нас, сли́шить от всіх: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну неруши́мую боже́ственную вселе́нній почита́єм тя, живоно́сний Кре́сте, зане́ соді́лавий тя Творе́ць не́ба і землі́ ру́ці на тебі́ распростре́, о стра́ннаго сли́шанія! Научи́во всіх возглаша́ти:","Ра́дуйся, основа́ніє благоче́стія;","ра́дуйся, побі́до наслі́дствующих.","Ра́дуйся, ми́сленнаго Амали́ка прогоня́яй;","ра́дуйся, рука́ма Ія́ковлевима прообразова́нний.","Ра́дуйся, ти бо возобрази́л єси́ древне́йшия сі́ні;","ра́дуйся, ти бо іспо́лнил єси́ пророкоглаго́ланния гла́си.","Ра́дуйся, Спаси́теля всіх носи́вий;","ра́дуйся, губи́теля душ упраздни́вий.","Ра́дуйся, і́мже со а́нгели соєдини́хомся;","ра́дуйся, єго́же ра́ди сві́том озари́хомся.","Ра́дуйся, я́ко почита́юще покланя́ємся тебі́;","ра́дуйся, я́ко восклиця́юще взива́єм к тебі́:","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє умаля́ється, послі́довати хотя́щеє ізоби́лію мно́гому чуде́с твої́х: і́бо похва́л мно́жество а́ще принесе́м ті, о Кресті́ честни́й, нічто́же соверша́єм досто́йно, я́же дал єси́ нам: но у́бо возопії́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Светопода́тельную зарю́ су́щим во тьмі да́руєть Крест живодарова́тельний сей: невеще́ственний бо прия́т світ, і к ра́зуму боже́ственному наставля́єть вся, возвиша́єть же, ни́ні возвиша́єм, ум наш воспіва́ти сія́:","Ра́дуйся, світи́ло, су́щим во тьмі сія́ющеє;","ра́дуйся, звіздо́, мир озаря́ющая.","Ра́дуйся, мо́лніє, христоуби́йці ослепля́ющая;","ра́дуйся, гро́ме, неві́рния ужаса́яй.","Ра́дуйся, я́ко ли́ки правосла́вних украси́л єси́;","ра́дуйся, я́ко тре́бища і́дольськая сокруши́л єси́.","Ра́дуйся, єго́же о́браз с небесе́ яви́ся;","ра́дуйся, єго́же благода́тію лука́вство прогна́ся.","Ра́дуйся, умерщвле́ніє пло́ті зна́менуяй;","ра́дуйся, воста́ніє страсте́й убива́яй.","Ра́дуйся, на не́мже Христо́с расп'я́ся;","ра́дуйся, і́мже весь мир спасе́ся.","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 12","ps":["Благода́ть дарова́ти челові́ком восхоті́в, Христо́с ру́ці на Кресті́ распростре́, призива́яй вся язи́ки, і да́руєть Ца́рство Небе́сноє всім пою́щим єму́ піснь досто́йно, і с ві́рою вопію́щим: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще піснь сію́, Крест восхваля́єм с любо́вію, я́ко дре́во Госпо́днє одушевле́нноє: на нем бо распе́нся пло́тію Влади́чествуяй го́рніми си́лами, освяти́ ни, просла́ви і научи́ вопи́ти тому́ сицева́я:","Ра́дуйся, Кре́сте, ми́сленний мечу́;","ра́дуйся, святи́х свято́є созерца́ніє.","Ра́дуйся, проро́ков і пра́ведних предвозвіще́ніє;","ра́дуйся, Христо́во світоно́сноє во́їнствованіє.","Ра́дуйся, добро́то і ві́нче царе́й благочести́вих;","ра́дуйся, держа́во і крі́посте ієре́єв благогові́йних.","Ра́дуйся, і́стини украше́ніє благосла́внійшеє;","ра́дуйся, спасе́нія приста́нище благоприя́тнійшеє.","Ра́дуйся, всіх сві́тлоє удобре́ніє;","ра́дуйся, сино́в неві́рних прогна́ніє.","Ра́дуйся, сві́та непоро́чнаго світи́льниче;","ра́дуйся, душі́ моєя́ ра́дованіє.","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 13","ps":["О всепі́тоє Дре́во, носи́вшеє всіх святи́х святі́йшеє Сло́во! Си́лою на тебі́ Расп'я́таго от вся́кия ізба́ви напа́сти всіх, і ві́чния ізми́ му́ки Тому́ вопію́щия: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели с небесе́ неви́димо окружа́ють Крест живоно́сний в стра́сі, і светопода́тельную благода́ть оби́льно подаю́ща ни́ні ві́рним ви́дяще, ужаса́ються і стоя́ть вопію́ще к нему́ сицева́я:","Ра́дуйся, Кре́сте, вселе́нния храни́телю;","ра́дуйся, Це́ркве прославле́ніє.","Ра́дуйся, ісціле́нія ізоби́льно істоча́яй;","ра́дуйся, преді́ли ми́ра просвіща́яй.","Ра́дуйся, дре́во живоблагоуха́нноє і чуде́с сокро́вище;","ра́дуйся, пречу́дний благода́тей пода́телю.","Ра́дуйся, я́ко єси́ подно́жіє боже́ственноє;","ра́дуйся, я́ко положе́н бил єси́ всім на поклоне́ніє.","Ра́дуйся, ча́ше, некта́ра іспо́лненная;","ра́дуйся, світи́льниче го́рнія сві́тлости.","Ра́дуйся, і́мже вся твар благословля́ється;","ра́дуйся, і́мже поклоне́ніє Творцю́ возсила́ється.","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Кондак 1","ps":["О всеспаси́тельний Кре́сте і всечестни́й, тебі́ покланя́ємся ві́рнії і велича́єм, ра́дующеся боже́ственному твоєму́ воздви́женію: но я́ко побі́ди зна́меніє і ору́жіє непреобори́моє, огради́ і покри́й твоє́ю благода́тію тебі́ вопію́щия:","Ра́дуйся, животворя́щий Кре́сте Госпо́день."]},{"h":"Молитва","ps":["Да воскре́снеть Бог, і расточа́ться вразі́ Єго́, і да біжа́ть от лиця́ Єго́ ненави́дящії Єго́. Я́ко ісчеза́єть дим, да ісче́знуть; я́ко та́єть воск от лиця́ огня́, та́ко да поги́бнуть бі́си от лиця́ лю́б'ящих Бо́га, і зна́менующихся кре́стним зна́менієм, і во весе́лії глаго́лющих: ра́дуйся, пречестни́й і животворя́щий Кре́сте Госпо́день, прогоня́яй бі́си си́лою на тебі́ проп'я́таго Го́спода на́шего Ісу́са Христа́, во ад сше́дшаго і попра́вшаго си́лу дия́волю, і дарова́вшаго нам тебе́, Крест Свой честни́й, на прогна́ніє вся́каго супоста́та. О пречестни́й і животворя́щий Кре́сте Госпо́день, помога́й мі со свято́ю Госпоже́ю Ді́вою Богоро́дицею, і со всі́ми святи́ми во ві́ки. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Спаси́, Го́споди, лю́ди Твоя́ / і благослови́ достоя́ніє твоє́, / побі́ди правосла́вним христия́ном / на сопроти́вния да́руя / і Твоє́ сохраня́я // Кресто́м Твої́м жи́тельство."]},{"h":"Кондак, глас 8","ps":["Вознеси́йся на Крест Во́лею, / тезоімени́тому Твоєму́ но́вому жи́тельству / щедро́ти Твоя́, да́руя, Христе́ Бо́же, / возвесели́ нас си́лою Твоє́ю, / побі́ди дая́ нам на супоста́ти, / посо́біє іму́щему Твоє́ ору́жіє ми́ра, // непобіди́мую побі́ду."]},{"h":"Величання","ps":["Велича́єм Тя, / Живода́вче Христе́, / і чтим Крест Твой святи́й, / і́мже нас спасл єси́, // от рабо́ти вра́жия."]}],"notes":[]},{"u":"Акафіст Божественним Страстям Христовим","e":"Akathist to the Divine Passion of Christ","secs":[{"h":"Кондак 1","ps":["Взбра́нний Воєво́до і Го́споди Небесе́ і землі́, Тебі́, Царя́ Безсме́ртнаго, зря́щи на Кресті́ ви́сяща, вся твар ізміни́ся, не́бо ужасе́ся, основа́нія землі́ восколеба́шася. Ми же, недосто́йнії, благода́рственноє поклоне́ніє Твоєму́ нас ра́ди страда́нію принося́ще, с разбо́йником вопіє́м Ті:","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Ікос 1","ps":["А́нгелов ликостоя́нія восполня́я, не от А́нгел восприя́л єси́, но мене́ ра́ди, Бог сий, челові́к бив, челові́ка, гріх ра́ди уме́рша, животворя́щим Ті́лом і Кро́вію Твоє́ю оживи́л єси́, ті́мже, толи́цій любві́ Твоє́й благода́рні су́ще, вопіє́м Ті:","Ісу́се Бо́же, Люби́ Предві́чная, та́ко о нас земноро́дних возблаговоли́вий;","Ісу́се, ми́лосте безмі́рная, к челові́ком па́дшим до́лу низше́дий.","Ісу́се, в плоть на́шу оболки́йся і сме́ртію Своє́ю сме́рти де́ржаву разруши́вий;","Ісу́се, Боже́ственними Твої́ми Та́їнами нас обожи́вий.","Ісу́се, страда́ньми і Кресто́м Твої́м весь мир іскупи́вий;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 2","ps":["Виді́в Тя А́нгел во вертогра́ді Гефсима́нстем до по́та крова́ва в моли́тві подвиза́ющася, предста́в укріпля́ше Тя, єгда́ я́ко бре́м'я тя́жкоє гріси́ на́ші отяготі́ша на Тебі́: Ти бо, Ада́ма поги́бшаго на ра́мо восприї́м, Отцю́ предста́вил єси́, прекло́нь колі́на моля́ся. О сем у́бо с ві́рою і любо́вію пою́ Тебі́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зума неразуме́нна во́льнаго Твоєго́ страда́нія не уразумі́ша іуде́є: сего́ ра́ди єгда́ в нощі́ со світи́льники і́щущим Тя рекл єси́: Аз єсьм; а́ще і падо́ша на землі́, но по сем связа́вше Тя, ведо́ша на суди́щі: ми же на сем путі́, припа́дающе к Тебі́, с любо́вію зове́м:","Ісу́се, Сві́те ми́ра, от ми́ра лука́ваго возненави́дінний;","Ісу́се, живи́й во Сві́ті Непресту́пнем, от о́бласти те́мния я́тий.","Ісу́се, Си́не Бо́жий Безсме́ртний, от си́на поги́белі на смерть указа́нний;","Ісу́се, в Не́мже льсти ність, от преда́теля ле́стію лобза́нний.","Ісу́се, ту́не Себі́ всім подава́яй, за сребре́нники прода́нний;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 3","ps":["Си́лою Божества́ Твоєго́ проре́кл єси́ трикра́тноє отверже́ніє ученику́. Он же посе́м, а́ще і отрече́ся Тебі́ с кля́твою, оба́че, єгда́ узрі́ Тя во дворі́ архієре́йстім, Го́спода своєго́ і Учи́теля, умили́вся се́рдцем, ізше́д вон пла́кася го́рко: «При́зри у́бо і на м'я, Го́споди, і порази́ жесто́коє се́рдце моє́, да слеза́ми мої́ми оми́ю гріхи́ моя́, поя́ Тебі́: Аллилу́я»."]},{"h":"Ікос 3","ps":["Імі́яй воі́стину власть по чи́ну Мелхіседе́кову, я́ко Архієре́й во ві́ки, стал єси́ пред беззако́нним первосвяще́нником Кая́фою, Влади́ка і Госпо́дь всіх; от Твої́х у́бо рабо́в прия́вий муче́ніє, прийми́ от нас сицева́я:","Ісу́се безці́нний, ці́ною ку́пленний, стяжи́ м'я в Твоє́ ві́чноє наслі́діє;","Ісу́се, жела́ніє всіх, от Петра́ стра́ха ра́ди отве́рженний, не отве́ржи м'я, грішна́го.","Ісу́се, А́гнче незло́биве, от лю́тих ве́прей терза́ємий, ізми́ м'я от враг мої́х;","Ісу́се Архієре́ю, Своє́ю Кро́вію вше́дий во Свята́я Святи́х, очисти́ м'я от скверн пло́тських.","Ісу́се свя́занний, імі́яй власть в'яза́ти і ріши́ти, разріши́ моя́ тя́жкая прегріше́нія;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 4","ps":["Бу́рею христоуби́йства ди́шуще іуде́є, послу́шавше глас отця́ лжі і человікоуби́йці іскони́, дия́вола, отверго́ша Тебі́, пра́вий Путь, І́стину і Живо́т; ми же Тя, Хри́ста, Бо́жию си́лу, в Не́мже вся сокро́вища прему́дрості і ра́зума сокрове́на суть, іспові́дующе, вопіє́м: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Пила́ть кро́ткия Твоя́ глаго́ли, а́ки досто́йнаго сме́рті предаде́ Тя на проп'я́тіє, а́ще і сам свиді́тельствоваше, я́ко ні єди́ния вини́ обрі́те в Тебі́: ру́ці у́бо свої́ уми́, но се́рдце оскверни́: ми же, чудя́щеся та́йні во́льнаго страда́нія Твоєго́, со умиле́нієм зове́м:","Ісу́се, Си́не Бо́жий і Си́не Ді́ви, от сино́в беззако́нія уму́ченний;","Ісу́се, пору́ганний і обнаже́нний, дая́й лі́поту кри́ном се́льним і одіва́яй не́бо о́блаки.","Ісу́се, насище́нний ра́нами, п'ятію́ хлі́би п'ять ти́сящ наси́тивий;","Ісу́се, Царю́ всіх, вмі́сто да́ни любве́ і благодаре́нія жесто́кия му́ки приє́мий.","Ісу́се, нас ра́ди весь день я́звленний, уврачу́й я́зви душ на́ших;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 5","ps":["Богото́чною Кро́вію Твоє́ю весь обле́клся єси́, одія́йся сві́том, я́ко ри́зою. Вім, воі́стину вім со проро́ком, почто́ червле́ни ри́зи Твоя́: аз, Го́споди, аз гріхми́ мої́ми уязви́х Тя; Тебе́ у́бо, мене́ ра́ди уя́звленному, благода́рственно зову́: Аллилу́я."]},{"h":"Ікос 5","ps":["Прови́дів Тя в ду́сі Богоглаго́ливий Іса́я, безче́стієм і ра́нами іспо́лнена, ужа́сся вопія́ше: «Ви́діхом Єго́, і не імі́яше ви́да, ні добро́ти». Ми же, зря́ще Тя на Кресті́, с ві́рою і удивле́нієм зове́м:","Ісу́се, безче́стіє терп'я́й, челові́ка сла́вою і че́стію вінча́вий;","Ісу́се, на Него́же А́нгели зрі́ти не мо́гуть, по лани́тома зауше́нний.","Ісу́се, по главі́ тро́стію ударе́нний, преклони́ во смире́ніє главу́ мою́;","Ісу́се, сві́тлая Твоя́ очеса́ кро́вію омраче́нная імі́вий, отврати́ очі́ моя́, є́же не ви́діти суєти́.","Ісу́се, от ног до глави́ не імі́вий ці́лости, всего́ ці́ла і здра́ва сотвори́ м'я;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 6","ps":["Пропові́дник Твоєго́ незло́бія я́влься Пила́ть, показа́ наро́ду нічто́же би́ти в Тебі́ досто́йно сме́рті; но іуде́є, я́ко зві́ри ди́вії кров узрі́вше, скрежета́ху на Тя зуби́ свої́ми, «распни́, распни́ Єго́», вопію́ще; ми же, лобиза́юще пречи́стия я́зви Твоя́, зове́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ в позо́р і удивле́ніє А́нгелом і челові́ком глаго́лющу о Тебі́ Пила́ту: «Се, челові́к». Прийді́те у́бо, пору́ганному нас ра́ди Ісу́су поклоні́мся, вопію́ще:","Ісу́се, Тво́рче і Судіє́ всіх, от тва́рі Своєя́ суди́мий і му́чимий;","Ісу́се, прему́дрости Пода́телю, отві́та безу́мним не да́вий.","Ісу́се, Врачу́ уя́звленних гріхми́, даждь мі врачевство́ покая́нія;","Ісу́се, Па́стирю пораже́нний, порази́ бісо́в, іскуша́ющих м'я.","Ісу́се, плоть іми́й сокруше́нну, сокруши́ се́рдце моє́ стра́хом Твої́м;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 7","ps":["Хотя́й челові́ка от рабо́ти вра́жия ізба́вити, смири́л єси́ Себе́ пред враги́ Твої́ми, Ісу́се, і, я́ко а́гнець безгла́сен на заколе́ніє веде́н бил єси́, везді́ я́зви терп'я́й, да всего́ ісціли́ши челові́ка, зову́ща: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вноє показа́л єси́ долготерпі́ніє, єгда́ во́їни, руга́ющеся Тебі́, по глаго́лу непра́веднаго судії́, люті́йшими ра́нами уязвля́ху Пречи́стоє Ті́ло Твоє́, я́ко обагри́тися єму́ от ног до глави́ кро́вію. Сего́ ра́ди со слеза́ми вопіє́м Ті:","Ісу́се человіколюби́вий, от челові́к те́рнієм увінча́нний;","Ісу́се, Божество́м безстра́стний, стра́сті терп'я́й, да нас от страсте́й свободи́ши.","Ісу́се, Спа́се мой, спаси́ м'я, пови́ннаго всім му́кам;","Ісу́се, всі́ми оста́вленний, Утвержде́ніє моє́, утверди́ м'я.","Ісу́се, от всіх оскорбле́нний, Ра́досте моя́, возвесели́ м'я;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 8","ps":["Ди́вно і стра́нно яви́стася Тебі́ Моїсей і Ілія́ на Фаво́рі, глаго́люща о ісхо́ді Твоє́м, єго́же ни́ні скончава́єши во Ієрусали́мі. Та́мо у́бо ви́дівша сла́ву Твою́, зді же спасе́ніє на́ше узре́вша, зову́ть: Аллилу́я."]},{"h":"Ікос 8","ps":["Везді́ от іуде́й гони́мий, мно́гия, ра́ди мно́жества гріхо́в мої́х, претерпі́л єси́ поноше́нія і му́ки: єди́ни бо Тя проти́вна би́ти ке́сарю глаго́лють, друзі́ї я́ко злоді́я осужда́ють, іні́ї же: «Возьми́, возьми́ і распни́», – вопію́ть. От всіх у́бо осужде́нному, і на проп'я́тіє ведо́мому, Тебі́, Го́споду, із глубини́ душі́ глаго́лем:","Ісу́се, непра́ведно осужде́нний, Судіє́ наш, не осуди́ нас по діло́м на́шим;","Ісу́се, ізнемога́яй на путі́ под Кресто́м, си́ло моя́, в час ско́рби і озлобле́нія моєго́ не оста́ви мене́.","Ісу́се, взива́яй о по́мощі к Отцю́, Подвигополо́жниче мой, в не́мощі моє́й укріпи́ м'я;","Ісу́се, безче́стіє приє́мий, Сла́во моя́, от Сла́ви Твоєя́ не отри́ни мене́.","Ісу́се, О́бразе пресві́тлия Іпоста́си О́тчія, преобрази́ моє́ нечи́стоє і мра́чноє житіє́;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 9","ps":["Все єстество́ см'яте́ся, зря Тебе́ на Кресті́ пові́шена, на небесі́ солнце́ лучи́ своя́ скри, земля́ потрясе́ся, заві́са хра́ма раздра́ся, каме́ніє распаде́ся, ад уме́ршія ізве́рже: ми же покланя́ємся на мі́сті, іді́же стоя́сте пречи́стії но́зі Твої́, пою́ще: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния, а́ще і мно́го глаго́лють, но не мо́гуть досто́йнаго благодаре́нія возда́ти Боже́ственним страсте́м Твої́м, Человіколю́бче: на́ша же душа́ і ті́ло, се́рдце і всі соста́ви со умиле́нієм к Тебі́ взива́ють:","Ісу́се, пригвожде́йся на Кресті́, пригвозди́ і упраздни́ рукописа́ніє гріхо́в на́ших;","Ісу́се, ру́ці со Креста́ простира́яй ко всім, привлеци́ і м'я, заблу́дшаго.","Ісу́се, Две́ре овця́м, в ре́бра прободе́нний, введи́ м'я я́звами Твої́ми в черто́г Твой;","Ісу́се, пло́тію расп'я́тий, распни́ плоть мою́ со страстьми́ і похотьми́.","Ісу́се, скончава́яйся в му́ках, даждь мі, да се́рдце моє́ не су́дить і́но что ві́діти, то́чію Тебі́ ра́сп'ята;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й мир, сліпи́х, хроми́х, прокаже́нних, німи́х і глухи́х ісціли́л єси́, духо́в лука́вих отгна́л єси́; неразу́мнії же іуде́є, зло́бою ди́шуще і за́вистію му́чими, пригвозди́ша Тя ко Кресту́, не ві́дуще пі́ти: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Преві́чний, Ісу́се, весь стра́ждеши за моє́ невоздержа́ніє, да всего́ м'я чи́ста сотвори́ши, во всем обра́з нам подая́й, да послі́дуєм стопа́м Твої́м, зову́ще:","Ісу́се, Люби́ неізслі́димая, распе́ншим Тя гріха́ не поста́вивий;","Ісу́се, с во́плем крі́пким і со слеза́ми во вертогра́ді моля́йся, научи́ і нас моли́тися.","Ісу́се, вся проро́чествія о Тебі́ іспо́лнивий, іспо́лни во благи́х жела́нія се́рдця на́шего;","Ісу́се, дух Твой в ру́ці Отцю́ преда́вий, в час ісхо́да моєго́ прийми́ дух мой.","Ісу́се, ри́зи Твоя́ разділи́ти не возбрани́вий, кро́тко ду́шу мою́ от ті́ла отділи́;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє приноша́ше Тебі́ Всенепоро́чная Ма́тер Твоя́, глаго́лющи: «А́ще і стра́ждеши на Кресті́, но вім Тя, із чре́ва пре́жде денни́ці от Отця́ рожде́нна, ви́жду бо, я́ко твар вся состра́ждеть Тебі́; предає́ши дух Твой Отцю́, і Мой дух прийми́ і не оста́ви Мене́, зову́щую: Аллилу́я»."]},{"h":"Ікос 11","ps":["Я́ко світоприє́мная свіща́, у Креста́ Твоєго́ горя́ще любо́вію к Тебі́, і Ма́тернею Ді́ва Пренепоро́чная обдержа́шеся болі́знію, заходя́щу Тебі́ во гроб і́стинному Со́лнцю Пра́вди, с Не́юже і се́рдця на́шего моли́тви прийми́ сицеви́я:","Ісу́се, вознеси́йся на дре́во, да нас, па́дших, совознесе́ши ко Отцю́ Своєму́;","Ісу́се, ді́вственнику Присноді́ву в Ма́тер дарова́вий, да нас ді́вству і чистоті́ научи́ши.","Ісу́се, Тебе́, Бо́га Сло́ва ро́ждшей, ученика́ Богосло́ва вручи́вий, вручи́ і нас всіх Єя́ Ма́тернему заступле́нію;","Ісу́се, ми́ра і а́да Побіди́телю, побіди́ неві́ріє, го́рдость жите́йськую і по́хоть оче́с, в нас живу́щия.","Ісу́се, сме́рті держа́ви разруши́телю, ві́чния сме́рти ізба́ви м'я;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 12","ps":["Благода́ть Твою́ пода́ждь мні, Ісу́се, Бо́же мой, прийми́ м'я, я́коже прия́л єси́ Іо́сифа с Никоди́мом, да, я́ко чи́стую плащани́цю, ду́шу мою́ принесу́ Тебі́ і воня́ми доброді́телей пома́жу пречи́стоє ті́ло Твоє́, і, я́ко во гро́бі, в сердці́ моє́м імі́ю Тя, зови́й: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ во́льноє расп'я́тіє, покланя́ємся страсте́м Твої́м, Христе́, ві́руєм с со́тником, я́ко воі́стину Бо́жий Син єси́, прийти́ імі́яй на о́блаціх с си́лою і сла́вою мно́гою; тогда́ у́бо не посрами́ нас, Кро́вію Твоє́ю іскупле́нних і та́ко вопію́щих:","Ісу́се многострада́льний, ри́данієм Ді́ви Ма́тере Твоєя́ ві́чнаго пла́ча ісхити́ ни;","Ісу́се, от всіх оста́вленний, не остави́ м'я єди́наго в час сме́рти моєя́.","Ісу́се, с Магдали́ною нога́м Твої́м каса́ющася, прийми́ м'я;","Ісу́се, с преда́телем і распе́ншими Тя не осуди́ мене́.","Ісу́се, с разбо́йником благоразу́мним в рай введи́ м'я;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 13","ps":["О Ісу́се Христе́, А́гнче Бо́жий, взе́мляй гріхи́ ми́ра, прийми́ ма́лоє сіє́ от всея́ душі́ на́шея приноси́моє Тебі́ благодаре́ніє і ісціли́ ни спаси́тельними Твої́ми страда́ньми от вся́кия болі́зні душе́вния і тіле́сния, огради́ ни Кресто́м Твої́м от враг ви́димих і неви́димих і при кончи́ні живота́ на́шего не оста́ви нас, да сме́ртію Твоє́ю ізба́вльшеся ві́чния сме́рти, ви́ну зове́м Тебі́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов ликостоя́нія восполня́я, не от А́нгел восприя́л єси́, но мене́ ра́ди, Бог сий, челові́к бив, челові́ка, гріх ра́ди уме́рша, животворя́щим Ті́лом і Кро́вію Твоє́ю оживи́л єси́, ті́мже, толи́цій любві́ Твоє́й благода́рні су́ще, вопіє́м Ті:","Ісу́се Бо́же, Люби́ Предві́чная, та́ко о нас земноро́дних возблаговоли́вий;","Ісу́се, ми́лосте безмі́рная, к челові́ком па́дшим до́лу низше́дий.","Ісу́се, в плоть на́шу оболки́йся і сме́ртію Своє́ю сме́рти де́ржаву разруши́вий;","Ісу́се, Боже́ственними Твої́ми Та́їнами нас обожи́вий.","Ісу́се, страда́ньми і Кресто́м Твої́м весь мир іскупи́вий;","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Кондак 1","ps":["Взбра́нний Воєво́до і Го́споди Небесе́ і землі́, Тебі́, Царя́ Безсме́ртнаго, зря на Кресті́ ви́сяща, вся твар ізміни́ся, не́бо ужасе́ся, основа́нія землі́ восколеба́шася. Ми же, недосто́йнії, благода́рственноє поклоне́ніє Твоєму́ нас ра́ди страда́нію принося́ще, с разбо́йником вопіє́м Ті:","Ісу́се, Си́не Бо́жий, пом'яни́ нас, єгда́ при́йдеши во Ца́рствії Твоє́м."]},{"h":"Молитва","ps":["На Кресті́ пригвожде́нний за ни, Ісу́се Христе́, Єдиноро́дний Бо́га Отця́ Си́не, ми́лости, любве́ і щедро́т неізчерпа́ємая бе́здно! Вім, я́ко гріхо́в ра́ди мої́х, от неізрече́ннаго человіколю́бія, Кров Твою́ пролія́ти на Кресті́ ізво́лил єси́, ю́же аз, окая́нний і неблагода́рний, досе́лі скве́рними мої́ми ді́ли попира́х і нівочто́же вміня́х. Тім у́бо із глубини́ беззако́нія і нечистоти́ моєя́ у́мнима очи́ма на Расп'я́таго Тя на Кресті́ Іскупи́теля моєго́ воззрі́в, со смире́нієм і ві́рою во глубину́ язв, Твоєго́ милосе́рдія іспо́лненних, себі́ поверга́ю, гріхо́в проще́нія і скве́рнаго житія́ моєго́ ісправле́нія прося́. Ми́лостив бу́ди мні, Влади́ко і Судіє́ мой, не отри́ни м'я от лиця́ Твоєго́, но всеси́льною Твоє́ю руко́ю Сам м'я к Тебі́ обрати́ і на путь і́стиннаго покая́нія наста́ви, да отни́ні положу́ спасе́нія моєго́ нача́ло. Боже́ственними страда́ньми Твої́ми укроти́ моя́ плотські́я стра́сті; ізлія́нною Твоє́ю Кро́вію очи́сти моя́ душе́вния скве́рни; расп'я́тієм Твої́м распни́ м'я ми́ру с собла́знами єго́ і похотьми́; Кресто́м Твої́м огради́ м'я от неви́димих враг, лов'я́щих ду́шу мою́. Прободе́нними нога́ми Твої́ми от вся́каго путі́ лука́ваго возбрани́ нога́м мої́м; прободе́нними рука́ми Твої́ми ру́ці мої́ от вся́каго неуго́днаго Тебі́ ді́ла воздержи́. Пригвожде́нний пло́тію, пригвозди́ стра́ху Твоєму́ плоть мою́, да уклони́вся от зла, творю́ бла́го пред Тобо́ю. Преклони́вий главу́ Твою́ на Кресті́, к землі́ смире́нія приклони́ вознесе́нную мою́ горди́ню; вінце́м Твої́м терно́вим огради́ моя́ ушеса́, во є́же не сли́шати неполе́знаго; желч уста́ми вкуси́вий, положи́ хране́ніє нечи́стим усто́м мої́м; отве́рстоє копіє́м імі́яй се́рдце, се́рдце чи́сто во мні сози́жди; всі́ми Твої́ми я́звами, всего́ м'я сла́дці в любо́в Твою́ уязви́, да Тебі́, Го́спода моєго́, возлюблю́ все́ю душе́ю, всім се́рдцем, все́ю крі́постію і всім помишле́нієм. Даждь мі Себі́ стра́нна і неіму́ща, гді глави́ подклони́ти; даждь мі Себі́ Всеблага́го, ізбавля́ющаго ду́шу мою́ от сме́рти; даждь мні Себі́ Всесла́дкаго, услажда́ющаго м'я в ско́рбіх і напа́стіх Своє́ю любо́вію, да Єго́же пе́рвіє ненави́діх, прогнівля́х, от себе́ ізгоня́х і ко Кресту́ пригвожда́х, сего́ ни́ні возлюблю́, ра́дуяся прийму́ і сла́дці Крест Єго́ до конця́ жи́зні моє́й понесу́. Не даждь отсе́лі, о всеблаги́й Іскупи́телю мой, ні єди́ной моє́й во́лі соверша́тися, поне́же зла єсть і непотре́бна, да не па́ки впаду́ в тя́жкую рабо́ту ца́рствовавшаго во мні гріха́; но Твоя́ во́ля блага́я, спасти́ м'я хотя́щая, да соверша́ється во мні всегда́, є́йже м'я вруча́я, Тебі́, Расп'я́таго Го́спода моєго́, у́мним очесе́м моєго́ се́рдця представля́ю і молю́ із глубини́ душі́, да і в разлуче́нії моє́м от бре́ннаго моєго́ ті́ла, Тебе́ Єди́наго на Кресті́ Твоє́м узрю́, в ру́ці м'я защище́нія Своєго́ приє́млюща, і от возду́шних духо́в зло́би храня́ща, вселя́юща же со грі́шники, покая́нієм Тебі́ благоугоди́вшими. Амі́нь."]},{"h":"Інша молитва","ps":["Го́споди Ісу́се Христе́, Си́не Бо́га жива́го, Тво́рче не́ба і землі́, Спаси́телю ми́ра, се аз, недосто́йний і па́че всіх грішні́йший, смире́нно колі́на се́рдця моєго́ пред сла́вою вели́чества Твоєго́ преклони́в, воспіва́ю крест і страда́нія Твоя́, і благодаре́ніє Тебі́, Царю́ всіх і Бо́гу, приношу́, я́ко благоізво́лил єси́ вся труди́ і вся́кия біди́, напа́сти і муче́нія, я́ко челові́к, понести́, да всім нам во вся́ких печа́лях, ну́ждах і озлобле́ніїх состра́ждущий Помо́щник і Спаси́тель бу́деши. Вім, всеси́льне Влади́ко, я́ко вся сія́ Тебі́ у́бо не би́ша потре́бна, но челові́чеськаго ра́ди спасе́нія, да всіх нас іску́пиши от лю́тия рабо́ти вра́жия, Крест і страда́нія претерпі́л єси́. Что у́бо возда́м Тебе́, человіколю́бче, о всіх, я́же пострада́л єси́ мене́ ра́ди грі́шнаго; не вім, душа́ бо і ті́ло, і вся блага́я от Тебе́ суть, і вся моя́ Твоя́ суть, і аз Твой єсьм. То́чію на безчи́сленноє Твоє́, благоутро́бне Го́споди, милосе́рдіє наді́яся, пою́ Твоє́ неізрече́нноє долготерпі́ніє, велича́ю неісповіди́моє істоща́ніє, сла́влю Твою́ безмі́рную ми́лость, покланя́юся пречи́стим Страсте́м Твої́м і, вселюбе́зно лобиза́я я́зви Твоя́, вопію́: поми́луй м'я грі́шнаго, і сотвори́, да не безпло́ден бу́деть во мні Крест Твой святи́й, да причаща́яся зді с ві́рою страда́ніям Твої́м, сподо́блюся ви́діти і сла́ву Ца́рствія Твоєго́ на небесі́! Амі́нь."]},{"h":"Тропар, глас 8","ps":["Єгда́ сла́внії ученици́ на умове́нії ве́чері просвіща́хуся, тогда́ Іу́да злочести́вий сребролю́бієм неду́говав омрача́шеся, і беззако́нним судія́м Тебе́, Пра́веднаго Судію́, предає́ть. Виждь, імі́ній рачи́телю, сих ра́ди удавле́ніє употреби́вша. Біжи́ неси́тия душі́, Учи́телю такова́я дерзну́вшия. І́же о всіх Благи́й, Го́споди, сла́ва Тебі́."]},{"h":"Кондак, глас 8","ps":["Нас ра́ди Расп'я́таго, прийді́те, всі воспої́м, Того́ бо ви́ді Марі́я на дре́ві, і глаго́лаше: а́ще і расп'я́тіє терпи́ши, Ти єси́ Син і Бог Мой."]}],"notes":[]},{"u":"Акафіст воскресінню Лазаря","e":"Akathist to the Raising of Lazarus","secs":[{"h":"Кондак 1","ps":["Возбра́нний Воєво́до і а́да Побіди́телю, Ти, я́ко імі́яй побі́ду над сме́ртію, Ла́заря Четверодне́внаго із ме́ртвих воздви́гл єси́, і всім ра́дость, світ і воскресе́ніє яви́л єси́; ми же недосто́йнії Твоєму́ нас ра́ди снисхожде́нію благодаре́ніє принося́ще, от душі́ вопіє́м Тебі́:","Ісу́се, Ла́заря пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Ікос 1","ps":["А́нгельськія си́ли в ра́достний тре́петь прийдо́ша, зря Твоє́, Сладча́йший Ісу́се, во Вифа́нію прише́ствіє, іді́же Ти, не імі́яй гді главу́ подклони́ти і зло́бою іуде́йською везді́ гони́мий, всегда́ обріта́л єси́ по труді́х благові́стія поко́й душе́вний, мир, любо́в і тишину́ у дру́га Твоєго́ Ла́заря, єго́же і Сам до конця́ возлюби́л єси́ с се́страми єго́ Ма́рфою і Марі́єю, я́ко ті́ї всегда́ с ві́рою і любо́вію служа́ху Тебі́, слу́шающе при ногу́ Твоє́ю Сло́во Твоє́. Таково́є человіколю́бноє снисхожде́ніє Твоє́ воспомина́юще, со умиле́нієм серде́чним вопіє́м Тебі́:","Ісу́се, Люби́ Предві́чная, до любве́ к челові́ком до конця́ низше́дий.","Ісу́се, Ми́лосте Безмі́рная, Ла́заря с се́стри єго́ в любо́в Свою́ прия́вий.","Ісу́се, благослове́нний дом Ла́заря во днех пло́ті Своєя́ с любо́вію посіща́вий.","Ісу́се, Боже́ственним Сло́вом Твої́м лю́б'ящая Тя ду́ші та́мо в сла́дость, мно́го насища́вий.","Ісу́се, Вифа́нію, оте́чество Ла́заря, мі́стом поко́я Твоєго́ ізбра́вий.","Ісу́се, ве́лія діла́ си́ли і любве́ та́мо пре́жде Креста́ Твоєго́ яви́вий.","Ісу́се, Ла́заря пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Кондак 2","ps":["Ви́дяще се́стри пра́веднаго Ла́заря Ма́рфа і Марі́я, я́ко брат їх лю́тою болі́знію зіло́ стра́ждеть, не преда́шася уни́нію, не впадо́ша в отча́яніє, но к Тебі́, Го́споди, Ціли́телю неду́гов, со упова́нієм посла́сте, с ві́рою глаго́люще: “Го́споди, се єго́же лю́биши, боли́ть”. Сему́ послі́дующе, і ми во вся́ком обстоя́нії да не предаді́мся уни́нію, но с упова́нієм да вопіє́м Тебі́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум чист імі́ша ученици́ Твої́, Го́споди, оба́че не разумі́ша, почто́ а́біє не шел єси́ во Вифа́нію к дру́гу Твоєму́ Ла́зарю ісціли́ти єго́, єгда́ прия́л єси́ вість о лю́тім неду́зі єго́, но рекл єси́ прише́дшим от Ма́рфи і Марі́ї: “сія́ болі́знь ність к сме́рті, но к сла́ві Бо́жієй, да просла́виться Син Бо́жий єя́ ра́ди”. Ми же ни́ні ві́дуще, я́ко хоті́л єси́ сокрове́нную глубину́ ві́ри і любве́ їх яви́ти, і бо́льшеє чу́до пред страда́ніями Свої́ми соверши́ти, с любо́вію зове́м:","Ісу́се, любве́ по́лний, лю́б'ящия Тя сердца́ святи́х сесте́р Ла́заревих іспиту́яй.","Ісу́се Всеблаги́й, болі́знію бра́тнею к ча́янію ве́лія Сла́ви Бо́жия тіх обраща́яй.","Ісу́се, ве́лій в чудесі́х Свої́х, хотя́й над Ла́зарем всему́ ми́ру Сла́ву Свою́ яви́ти.","Ісу́се, Ди́вний в сові́тіх Свої́х, положи́вий во Вифа́нії вели́чія Своя́ соверши́ти.","Ісу́се, сме́рті не сотвори́вий, скорб'я́щим сестра́м Ла́заревим не боя́тися сме́рті бра́та повелі́вий.","Ісу́се, к сме́рті во́лею гряди́й, сомня́щимся ученико́м побі́ду над сме́ртію яви́ти восхоті́вий.","Ісу́се, Ла́заря пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Кондак 3","ps":["Си́лою Божества́ Твоєго́ ві́дуще, я́ко належи́ть Ті пре́жде Креста́ Твоєго́, Всеблаги́й Го́споди, яви́ти над Ла́зарем си́лу Свою́, да су́щії с Тобо́ю ученици́ не устраша́ться страда́ній Твої́х і уразумі́ють із ме́ртвих Воскресе́ніє Твоє́. Сего́ ра́ди, усли́шав, я́ко боли́ть Ла́зар, друг Твой, не поспеши́л єси́ ісціли́ти єго́, преби́л на не́мже бі мі́сті два дні, да боголюби́вия се́стри єго́ і пред лице́м сме́рті бра́та своєго́ пребу́дуть ві́рою і любо́вію горя́ще, пою́ще Тебі́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще предві́дініє Боже́ственноє, Всеблаги́й Го́споди, Ти рекл єси́ ученико́м Твої́м: “І́дем в Іуде́ю па́ки”, і пото́м: “Ла́зар друг наш у́спе, но іду́, да возбужу́ єго́”. Єгда́ же ученици́ не разумі́ша, мня́ще, я́ко о успе́нії сна єго́ глаго́леши, тогда́ необину́яся рекл єси́: “Ла́зар у́мре. І ра́дуюся вас ра́ди, да ві́руєте, я́ко не біх та́мо, но і́дем к нему́”. Тогда́ Фома́, ви́дів, я́ко ученици́ страх і́муть во Іуде́ю ідти́, я́ко ни́ні уже́ іска́ху Іуде́ї ка́менієм поби́ти Тя, со дерзнове́нієм рече́ їм: “і́дем і ми, да у́мрем с Ним”, науча́юще і нас без стра́ха послі́довати Тебі́ і воспіва́ти та́ко:","Ісу́се, дру́же Ла́зарев, дру́га Твоєго́ от сме́ртнаго успе́нія возста́вити гряди́й.","Ісу́се, Вифа́нії похвало́, і весь Ла́зареву ра́дость і воскресе́ніє неси́й.","Ісу́се, Люби́ Неізрече́нная, плач і рида́нія сесте́р Ла́заревих усли́шавий.","Ісу́се, Ми́лосте Безконе́чная, овча́ своє́ бездиха́нноє оживи́ти ізво́ливий.","Ісу́се, с Ла́зарем во Вифа́нії погребе́нним, погреби́ моя́ лю́тия прегріше́нія.","Ісу́се, с Ма́рфиними і Марі́їними слеза́ми прийми́ о грісі́х мої́х тя́жкая воздиха́нія.","Ісу́се, Ла́заря пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Кондак 4","ps":["Бу́рю внутр іму́ще помишле́ній сумни́тельних, Ма́рфа і Марі́я го́рко пролива́ху сле́зи над гро́бом Ла́заря, помина́юще со ско́рбію обітова́ніє Твоє́, я́ко болі́знь Ла́зарева не к сме́рті єсть, но к сла́ві Бо́жієй, зане́ ти́я лише́ни уже́ би́ша пре́жнія наде́жди, зря́ще бра́та своєго́ во гро́бі пребива́ніє і ті́ла єго́ разруше́ніє і смерде́ніє. Ти же, Го́споди, об ону́ страну́ Іорда́на ходя́ще, глаго́лал єси́ ученико́м Свої́м: Ра́дуються, дру́зі мої́, вас ра́ди, я́ко не бих та́мо, да уві́сте, я́ко вся могу́, Бог сий. І́дем у́бо оживи́ти єго́, я́ко да смерть я́ві ощути́ть сего́ побі́ду і соверше́нноє разруше́ніє, да воспоє́те со всі́ми ві́рними: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав свята́я пра́ведная Ма́рфа, я́ко Ти, Го́споди, во Вифа́нію гряде́ши, чети́ре дні Ла́зарю во гро́бі уже́ би́вшу, ізи́де во срі́теніє Тебі́, Марі́ї же до́ма сиде́вшей, і глаго́лаше Тебі́, утіше́нія і́щущи: “Го́споди, а́ще би єси́ зді бил, не би брат мой у́мерл. Но і ни́ні вім, я́ко єли́ка а́ще про́сиши у Бо́га, дасть Тебі́ Бог”. Сію́ ві́ру ско́рбния се́стри Ла́зареви во вели́цій печа́лі єя́ ви́дівше, со умиле́нієм в душі́ зове́м Тебе́:","Ісу́се, к четверодне́вному мертвецю́ стопи́ Своя́ напра́вивий, посіти́ і мене́ во гро́бі отча́янія су́щаго.","Ісу́се, во Вифа́нію прише́дий прия́ти в любо́в Свою́ скорб'я́щия сестри́, прийми́ і мене́ заблу́дшаго.","Ісу́се, Ма́рфу многотру́дную бесі́дою Своє́ю уті́шивий, уті́ши і мене́ о грісі́х скорб'я́щаго.","Ісу́се, Марі́ю с ча́янієм до́ма сиде́вшую не заби́вий, не забу́ди і мене́ во уни́ніє впа́дшаго.","Ісу́се, смерть, трепета́ти начина́ющую, прише́ствієм во Вифа́нію устраши́вий, сме́рті ві́чній не преда́ждь м'я.","Ісу́се, ад го́ркий топта́нієм ног Твої́х, к Вифа́нії гряду́щих, стра́ха іспо́лнивий, а́дських мук ізба́ви м'я.","Ісу́се, Ла́заря пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ нощни́й мрак разгоня́ющей подо́бно бисть предрече́ніє Твоє́, Го́споди, єго́же, я́ко Влади́ка живота́ і сме́рті, ізре́кл єси́ Ма́рфі, глаго́лющи: “Воскре́снеть брат твой”. Она́ же, я́ко єще́ немощна́я во ві́рі, коле́блющеся ві́ровати, я́ко брат єя́ мо́жеть ни́ні по сло́ву Твоєму́ із ме́ртвих возста́ти, глаго́ла Тебі́: “Вім, я́ко воскре́снеть во воскреше́ніє, в послі́дній день”. Ми же недосто́йнії Тебі́ Побіди́телю сме́рти с ві́рою вопіє́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів, я́ко се́рдце святи́я Ма́рфи, печа́лію пораже́нноє о сме́рті Ла́заря, не мо́жеть єще́ ві́ровати, я́ко і ни́ні, Го́споди, Ти си́лен єси́ із ме́ртвих воскреси́ти єго́, Ти рекл єси́ со вла́стію, я́ко живото́м і сме́ртію повеліва́яй, жела́ющи возбуди́ти ю от такова́го малоду́шія: “Аз єсьм Воскресе́ніє і Живо́т. Ві́руяй в М'я, а́ще і у́мреть, жив бу́деть”. Ми же сему́ Боже́ственному обітова́нію вне́млюще, і живо́т ві́чний улучи́ти хотя́ще, со упова́нієм зове́м Ті:","Ісу́се, прише́дий во Вифа́нію пропові́дати Воскресе́ніє, воскреси́ м'я во страстеіх всего́ істлі́вшаго.","Ісу́се, предвозвісти́вий Ма́рфі Ла́зарево воскреше́ніє, воззови́ м'я от мно́гих гріхо́во возсмерде́вшаго.","Ісу́се, обнови́вий ві́ру Ма́рфи во Воскресе́ніє, обнови́ ду́шу мою́ умерщвле́нную гріхми́.","Ісу́се, призва́вий всіх нас упова́ти о уме́рших, просвіти́ жизнь на́шу омраче́нную страстьми́.","Ісу́се, живи́ми і ме́ртвими облада́яй, не преда́ждь м'я го́ркой сме́рті в преіспо́дней ві́чно мно́ю облада́ти.","Ісу́се, живо́т ві́чний нам дарова́вий, пода́ждь мі наслі́діє блаже́нноє на небесі́х восприя́ти.","Ісу́се, Ла́заря пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам своє́ Воскресе́ніє."]},{"h":"Кондак 6","ps":["Пропові́дниця Твоєго́, Христе́, Божества́ яви́ся свята́я Ма́рфа, во іспові́данії своє́м Петру́, Верхо́вному Апо́столу Твоєму́, ра́вная: сія́ бо, єгда́ вопроше́на бисть от Тебе́, є́млеть ли ві́ру, я́ко всяк ві́руяй в Тя, а́ще і у́мреть, жив бу́деть, глаго́ла Тебі́: “Єй, Го́споди, аз ві́ровах, я́ко Ти єси́ Христо́с, Син Бо́жий, І́же в мир гряди́й”. Ми же сему́ іспові́данію с благогові́нієм вне́млюще, с ві́рою і любо́вію вопіє́м Тебі́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ но́вий світ ві́ри і наде́жди у святи́я пра́ведния Марі́ї, до́ма в ско́рбі сиде́вшей, єгда́ приї́де к ней сестра́ єя́ Ма́рфа і та́йно от прише́дших ко єя́ утіше́нію іуде́й возвісти́ єй о Твоє́м, Святи́й Го́споди, прише́ствії, глаго́люще: “Учи́тель прише́л єсть і глаша́єть тя”. Та же, сли́шавши сіє́, возста́ і ско́ро прише́дше па́дше, поклони́ся Тебі́ і лобиза́юще пречи́стії но́зі Твої́ і утіше́нія і́щущи, глаго́лаше Тебі́ со слеза́ми:","“Ісу́се, живота́ Нача́льниче, а́ще бил би єси́ зді, не би у́мерл мой брат”.","Ісу́се, сме́рті Разруши́телю, а́ще би прише́л єси́ сі́мо, не би лежа́л Ла́зар четверодне́вний во гро́бі.","Ісу́се, Уті́шителю До́брий, уті́ши в ско́рбі су́щую ду́шу мою́.","Ісу́се, Учи́телю Благи́й, научи́ м'я твори́ти во́лю Твою́.","Ісу́се, Наста́вниче безнаде́жних, наста́ви м'я с наде́ждою і терпі́нієм нести́ крест мой.","Ісу́се, Прибі́жище си́рих, даждь мі при ногу́ Твоє́ю обрісти́ в ско́рбі моє́й поко́й Твой.","Ісу́се, Ла́заря, пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Кондак 7","ps":["Хотя́щей Марі́ї ізли́ти при ногу́ Твоє́ю вся чу́вствія своя́ о Ла́зареві лише́нії і любо́в к Тебі́, Го́споди, Ти же уви́дів ю пла́чущуюся, і прише́дшії с не́ю іуде́ї пла́чущия, огорчи́лся єси́ ду́хом і возмути́лся єси́, челові́чеськоє показу́я, і прослези́лся єси́ Сам, да і ми немощні́ї, в ско́рбіх су́ще со дерзнове́нієм припа́дше к Тебі́, ізлива́єм в не́мощі із глубини́ душі́ сле́зи своя́, і со умиле́нієм вопіє́м Тебі́ прослези́вшемуся о на́ших ско́рбіх: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє і неізрече́нноє снисхожде́ніє і человіколю́біє кра́йнєє яви́л єси́, Сладча́йший Ісу́се, єгда́ зря Марі́їни сле́зи, прослези́лся єси́ Сам. Іуде́ї же ні́ції, ви́дяще, я́ко о Ла́зарі пла́чеши, глаго́лаху: “Виждь, ка́ко любля́ше єго́”. Друзі́ї же, в окамене́нії душ і серде́ць су́ще, не восхоті́ша разумі́ти Боже́ственноє сострада́ніє Твоє́ не́мощем на́шим, мня́ху самому́ Тебі́ не́мощну би́ти і глаго́лаху в Твоє́ посмія́ніє: “не можа́ше ли Сей, Отве́рзий о́чі сліпо́му, сотвори́ти, да і сей не у́мреть”. Ми же прославля́я человіколю́біє Твоє́, от душі́ вопіє́м Тебі́:","Ісу́се, сле́зи о Ла́зарі с се́стри єго́ істочи́вий, струя́ми сле́зними очи́сти гріхи́ мої́.","Ісу́се, Ма́рфини і Марі́їни сле́зи утоли́вий, пла́чем Свої́м утоли́ печа́лі моя́.","Ісу́се, тро́сти сокруше́нния не преломи́вий, богозда́нний храм душі́ моєя́ не сокруши́ во мні.","Ісу́се, льна куря́щася не угаси́вий, горя́щий світи́льник ві́ри і любве́ не погаси́ во мні.","Ісу́се долготерпіли́вий, не́мощем на́шим да́же до конця́ спострада́вий, в не́мощі моє́й укріпи́ м'я.","Ісу́се человіколюби́вий, да́же до возскорбе́нія за ни і до слез снизше́дий, ві́чнаго пла́ча ісхити́ м'я.","Ісу́се, Ла́заря пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Кондак 8","ps":["Стра́нно бі вопроша́ніє Твоє́, Христе́ Спа́се, єгда́ всім пла́чущим, Ти о Ла́зарі вопроша́л єси́: “Гді положи́сте єго́?”, зане́, я́ко Бог вся ві́дий, Ти предре́кл єси́ смерть єго́, ка́ко же ни́ні, бе́здна сий ві́дінія, не ві́си гді погребе́н єсть друг Твой? Оба́че ни́ні вопроша́єши не неві́дий, уві́діти хотя́й, но я́ко челові́к, челові́чеськи глаго́ля, хотя́й скорб'я́щия се́стри Ла́заря уті́шити і сего́ ра́ди гроб єго́ посіти́ти. Таково́є человіколю́бноє снисхожде́ніє Твоє́ сла́в'яще, поє́м Тебе́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь сий Любо́в, Весь сий жела́ніє на́ше, Го́споди Ісу́се, Ти, прише́д на гроб Ла́зарев, па́ки претя́ в себі́ о жестосе́рдії та́мо би́вших, повелі́л єси́ взя́ти ка́мень от гро́ба, да возсмерде́нієм сме́рті заградя́ться уста́ неві́рних. Ма́рфа же, па́ки явля́ющи не́мощ єстества́ челові́чеськаго, глаго́люще Тебі́: “Го́споди, уже́ смерди́ть, четверодне́вен бо єсть”. Оба́че Ти па́ки укріпи́л єси́ ю в малоду́шії єя́, глаго́люще: “не ріх ли ті, я́ко а́ще ві́руєши, у́зриши Сла́ву Бо́жию”. Марі́я же, зря́ще ка́мень отвале́н от гро́ба, в притре́петном ча́янії пребива́ше, ві́ру в молча́нії соблюда́ющи, і то́чію в се́рдці глаго́люще:","Ісу́се, ко гро́бу дру́га Ла́заря прише́дий, очи́сти ум мой от сумне́ній неві́рних.","Ісу́се, Сла́ву Бо́жию яви́ти восхоті́вий, сохрани́ се́рдце моє́ от по́хотей скве́рних.","Ісу́се, ка́мень от гро́ба Ла́заря отвали́ти повелі́вий, отвали́ ка́мень жестосе́рдія от гро́ба душі́ моєя́.","Ісу́се, глаго́лом уст Твої́х вся си́ли а́да устраши́вий, не устраши́ м'я явле́нієм обетова́нния Сла́ви Твоєя́.","Ісу́се Кротча́йший, кро́тко гро́бу Ла́заря предста́вий, кро́ткою душе́ю сподо́би м'я Твоє́ прише́ствіє ощути́ти.","Ісу́се Сладча́йший, мертвеця́ смердя́ща во гро́бі узрі́вий, смире́нним нра́вом пода́ждь мі Твою́ благода́ть лицезре́ти.","Ісу́се, Ла́заря пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Кондак 9","ps":["Все єстество́ А́нгельськоє см'яте́ся, єгда́ Ти, Чудотво́рче Го́споди, явля́я Сла́ву Свою́, я́ко Єдиноро́днаго от Отця́, пред лице́м мно́жества наро́днаго хвалу́ возда́л єси́ Небе́сному Отцю́, глаго́ля: “О́тче, благодарю́ Тя, я́ко усли́шал єси́ М'я”, і сія́ рек, гла́сом ве́ліїм воззва́л єси́: “Ла́заре, гряди́ вон” і єгда́ бездиха́нний повелі́ніє Твоє́ послу́шав, а́біє одушевле́н от сме́рти возста́ і ізи́де укро́єм рука́ма і нога́ма об'я́зан, да чу́до сіє́ зря́ще, вся колі́на небе́сних і земни́х і преіспо́дніх Тебі́ Побіди́телю сме́рти преклоня́ться, вопію́ще: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї богоглаго́ливії, а́ще і мно́го глаго́лють, но не возмо́гуть досто́йно просла́вити ве́ліє і стра́шноє чу́до Твоє́, Го́споди, єгда́ Ти Ла́заря Четверодне́внаго от ме́ртвих воздви́гл єси́, да Ма́рфу і Марі́ю, с ни́миже і всіх нас во ві́рі і наде́жді Воскресе́нія і безсме́ртія душі́ утверди́ши. Сего́ ра́ди мно́зі от іуде́й к Марі́ї прише́дших, ви́дівше, я́же Ти сотвори́л єси́ во Вифа́нії, ві́роваша в Тя, я́ко в Си́на Бо́жия і ра́достно принесо́ша Тебі́ похвали́ сицеви́я:","Ісу́се, Ла́заря ме́ртва Четверодне́вна воскреси́вий, і мене́ уме́рша страстьми́ воскреси́.","Ісу́се, дру́га Твоєго́ пово́йми свя́зана разріши́вий, і мене́ свя́зана у́зами гріха́ разріши́.","Ісу́се, мертвеця́ смердя́ща от гро́ба свободи́вий, і мене́ із гро́ба отча́янія ізведи́.","Ісу́се, а́гнця люби́маго от про́пастей а́да ісхи́тивий, і мене́ от ві́чния тьми кромі́шния сохрани́.","Ісу́се, повелі́нієм Живоно́снаго гла́са Твоєго́ воздви́гнувий смердя́щаго, і мене́ істлі́вшаго страстьми́ Сло́вом Твої́м оживи́.","Ісу́се, всеси́льною крі́постію Твоє́ю Ла́заря Четверодне́вна возста́вивий, і мене́ о́бщника тридне́внаго Воскресе́нія Твоєго́ покажи́.","Ісу́се, Ла́заря, пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Кондак 10","ps":["Спасти́ восхоті́л єси́ вся, Христе́ Спа́се, оба́че, си́нове тьми, зря́ще уме́ршаго Ла́заря, гла́сом Твої́м от тлі́нія возста́вша, не восхоті́ша в ожесточе́нії серде́ць свої́х уві́ровати в Тя, і ні́циї от них поідо́ша к первосвяще́нником і фарисе́єм, і возвісти́ша їм, я́же Ти сотвори́л єси́ во Вифа́нії. Ми же безу́мію їх не вдаю́щеся, но в о́бщеє Воскресе́ніє по обітова́нію Твоєму́ ві́рующе, Тебі́, Живода́вцю і Спаси́телю на́шему велегла́сно вопіє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ преві́чний, Ісу́се! Сті́ни ка́менния тве́рдо би́ша первосвяще́нници іуде́йстії, єгда́ усли́шавше, каково́є стра́шноє чу́до сотвори́л єси́ во Вифа́нії, сові́т восприя́ша на Тя, глаго́люще: “Что сотвори́м, я́ко Челові́к Сей мно́га зна́менія твори́ть”. Єди́н же от них, Кая́фа, архієре́й сий лі́ту тому́, рече́, я́ко у́не єсть, да Єди́н Челові́к у́мреть за лю́ди своя́, а не весь язи́к поги́бнеть. І от того́ у́бо дне совіща́ша, да убію́ть Тя, Христа́ Своєго́ і Влади́ку, вку́пі же і Ла́заря, я́ко мно́зі єго́ ра́ди прихожда́ху от іуде́й і ві́роваху в Тя. Сего́ ра́ди вопіє́м Ті си́це:","Ісу́се, Си́не Бо́жий Безсме́ртний, Ла́заря ра́ди, я́ко а́гнець незло́бивий на закла́ніє приугото́вленний.","Ісу́се, Спа́се наш, челові́ки суди́мий, от Кая́фи за лю́ди умре́ти нево́лею предрече́нний.","Ісу́се, на беззако́нном собо́рище вку́пі с Ла́зарем на смерть осужде́нний, не осуди́ нас на суди́щі Твоє́м.","Ісу́се, во ве́рной Вифа́нії, в дому́ Ла́заря печа́ль на ра́дость преложиви́й, пом'яни́ нас во Ца́рствії Твоє́м.","Ісу́се, Креста́ предначина́ніє во Вифа́нії соверши́вий, си́лою Креста́ Твоєго́ сохрани́ нас.","Ісу́се, льсти́вих фарисе́єв чудеси́ свої́ми устраши́вий, воскресе́нієм Ла́заря возвесели́ нас.","Ісу́се, Ла́заря пре́жде Стра́сті Твоєя́ із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє да принесе́ть Тебі́, Христе́ Спа́се наш, Вифа́нія ві́рная і Тобо́ю люби́мая, я́ко в ра́дость Ти преложи́л єси́ печа́ль єя́, Ла́заря, воспита́ніє єя́, із гро́ба воздвиза́я, і да не сі́туєть, я́ко на ма́лоє вре́м'я Ти отше́л єси́ во Єфре́м нариця́ємий град близ пусти́ні, іді́же ходи́л єси́ со ученики́ Свої́ми, первосвяще́нником за́повідь да́вшим, да і́муть Тя. Ми же, удивля́ющеся Твоєму́ о учениці́х пред страда́нії Твої́ми попече́нію, поє́м Тебе́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ ве́лій і неізрече́нний осія́ Вифа́нію, єгда́ пре́жде шести́ дній битія́ Па́схи Ти па́ки прише́л єси́ во весь сію́, Сладча́йший Ісу́се, іді́же лю́б'ящия Тя сотвори́ша Тебі́ пресла́вную ве́черю, Ла́зарево воскреше́ніє с ра́достію і благодаре́нієм воспомина́юще. Бі же ту і Ла́зар єди́н от возлежа́щих, Ма́рфа же с любо́вію мно́гою па́ки служа́ше Тебі́, Марі́я же от ізби́тка ра́дости, любве́ і благодаре́нія, приє́мше ли́тру ми́ра на́рда чи́ста многоці́нна, пома́за пречи́стії но́зі Твої́, і власи́ свої́ми отира́ше я, і хра́мина іспо́лнися вся от вони́ ма́сти благово́нния. Ми же недосто́йнії, в ра́дость о́них блаже́нних собесе́дников Твої́х прони́кнути жела́юще, со умиле́нієм мно́гим вопіє́м Тебі́ такова́я:","Ісу́се, с мертвеце́м воскре́сшим разділи́вий трапе́зу, даждь мі ви́ну наслажда́тися ві́чния Твоєя́ ве́чері на небесі́.","Ісу́се, Ла́заря по воскреше́нії єго́ небе́сною ра́достію іспо́лнивий, сподо́би м'я небе́сния ми́слити на землі́.","Ісу́се, Ма́рфу трудолюби́вую се уже́ второ́є на ве́чері послужи́ти Тебі́ удосто́ївий, прийми́ м'я на Твоє́ служе́ніє.","Ісу́се, Марі́ю, Бо́жиєю любо́вію горя́щую, но́зі Твої́ ми́ром пома́зати сподо́бивий, даждь мі ду́ха любве́ пламене́ніє.","Ісу́се, Вифа́нію странноприя́тієм Тя на ве́чері зіло́ возвесели́вий, возвесели́ м'я посреді́ трудо́в отдохнове́нієм.","Ісу́се, Ма́рфини сле́зи і Марі́їн плач Ла́заревим возста́нієм ско́ро уті́шивий, уті́ши м'я в ско́рбіх Твої́м посіще́нієм,","Ісу́се, Ла́заря пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Кондак 12","ps":["Благода́ть ве́лію дарова́л єси́, Христе́, воскреше́нієм Ла́заря благослове́нній вифани́йстей ві́си, восприя́вшей Тя. Нау́тріє сріта́ють Тя в Ієрусали́мі крест, злохуле́ніє, і поноше́нія от зло́бних фарисе́й, за́вистію ди́шащих, здісь же Ти обрі́л єси́ пре́жде креста́ любо́в, ра́дость, і мир о Ду́сі Свя́те. Сего́ ра́ди да бу́деть Тебі́ похвала́ ві́чная, Вифа́ніє, я́ко Зижди́теля странноприя́ти сподо́билася єси́: благоугото́вися, украси́ боже́ственне твоя́ вхо́ди, расшири́ преддве́рія твоя́, да і ми с тобо́ю воспоє́м просла́вившему тя Го́споду: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ із ме́ртвих Ла́зарево воскреше́ніє, поклоня́ємся вели́чію діл Твої́х, Христе́, прославля́єм вседержи́тельство Твоє́ і кра́йнєє снисхожде́ніє с неізрече́нним человіколю́бієм Твої́м і ві́руєм с Ма́рфою, я́ко воі́стину Ти єси́ Христо́с, Син Бо́жий, І́же в мир гряди́й, с Марі́єю же приседи́м при ногу́ Твоє́ю, внима́юще єди́ному на потре́бу Боже́ственному Сло́ву Твоєму́, і сподо́би нас моли́твами пра́веднаго Ла́заря, дру́га Твоєго́, ви́діти Твою́ сві́тлую над сме́ртью побі́ду, і живоно́сноє Воскресе́ніє Твоє́ вопію́щим Тебі́ та́ко:","Ісу́се, а́да Побіди́телю, с Ла́зарем Четверодне́вним із тьми кромі́шния гріха́ ізведи́ м'я.","Ісу́се, сме́рті Низложи́телю, с дру́гом Твої́м уме́ршим к жи́зні і воскресе́нію па́ки воззови́ м'я.","Ісу́се, Ла́заря на о́строві Ки́прі от зло́би фарисе́йськия спаси́й, і́миже ві́си судьба́ми спаси́ м'я.","Ісу́се, та́мо єго́ от Апо́стол во єпи́скопа поста́вивий, от Це́ркві Твоєя́ не отлучи́ м'я.","Ісу́се, тому́же омофо́р рука́ма Богома́тері істка́нний вручи́вий, под кро́вом Єя́ сохрани́ м'я.","Ісу́се, Ла́заря посіще́нія Пречи́стия во днех пло́ті Єя́ удосто́ївий, Тоя́ предста́тельства не лиши́ м'я,","Ісу́се, Ла́заря пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Кондак 13","ps":["О, Сладча́йший Ісу́се, всіх Ра́досте, Сві́те Ти́хий, Живо́т ми́ра і Воскресе́ніє на́ше! Прийми́ от нас, я́коже от Ма́рфи і Марі́ї сіє́ ма́лоє благодаре́ніє на́ше о Воскреше́нії Ла́заря от всея́ душі́ Тебі́ приноси́моє, і сотвори́ ни о́бщници би́ти того́ із гро́ба возста́нія, да всеси́льним Сло́вом Твої́м воздви́гнеши і нас от вся́каго паде́нія гріхо́внаго і сме́рті ві́чния, і сподо́биши ни получи́ти наслі́діє неув'яда́ємоє на небесі́х, іді́же со всі́ми святи́ми да воспоє́м Тебі́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськія си́ли в ра́достний тре́петь прийдо́ша, зря Твоє́, Сладча́йший Ісу́се, во Вифа́нію прише́ствіє, іді́же Ти, не імі́яй гді главу́ подклони́ти і зло́бою іуде́йською везді́ гони́мий, всегда́ обріта́л єси́ по труді́х благові́стія поко́й душе́вний, мир, любо́в і тишину́ у дру́га Твоєго́ Ла́заря, єго́же і Сам до конця́ возлюби́л єси́ с се́страми єго́ Ма́рфою і Марі́єю, я́ко ті́ї всегда́ с ві́рою і любо́вію служа́ху Тебі́, слу́шающе при ногу́ Твоє́ю Сло́во Твоє́. Таково́є человіколю́бноє снисхожде́ніє Твоє́ воспомина́юще, со умиле́нієм серде́чним вопіє́м Тебі́:","Ісу́се, Люби́ Предві́чная, до любве́ к челові́ком до конця́ низше́дий.","Ісу́се, Ми́лосте Безмі́рная, Ла́заря с се́стри єго́ в любо́в Свою́ прия́вий.","Ісу́се, благослове́нний дом Ла́заря во днех пло́ті Своєя́ с любо́вію посіща́вий.","Ісу́се, Боже́ственним Сло́вом Твої́м лю́б'ящая Тя ду́ші та́мо в сла́дость, мно́го насища́вий.","Ісу́се, Вифа́нію, оте́чество Ла́заря, мі́стом поко́я Твоєго́ ізбра́вий.","Ісу́се, ве́лія діла́ си́ли і любве́ та́мо пре́жде Креста́ Твоєго́ яви́вий.","Ісу́се, Ла́заря пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Кондак 1","ps":["Возбра́нний Воєво́до і а́да Побіди́телю, Ти, я́ко імі́яй побі́ду над сме́ртію, Ла́заря Четверодне́внаго із ме́ртвих воздви́гл єси́, і всім ра́дость, світ і воскресе́ніє яви́л єси́; ми же недосто́йнії Твоєму́ нас ра́ди снисхожде́нію благодаре́ніє принося́ще, от душі́ вопіє́м Тебі́:","Ісу́се, Ла́заря пре́жде Твоєя́ стра́сти із ме́ртвих воздви́гнувий, яви́ нам Своє́ Воскресе́ніє."]},{"h":"Молитва до Господа Ісуса Христа","ps":["Го́споди Ісу́се Христе́, Бо́же, Спаси́телю наш, Неісчерпа́ємая бе́здно ми́лости, щедро́т і любве́, сме́рти і гріха́ не сотвори́вий, і єще́ в раї́ опреділи́вий прароди́телем на́шим ві́чния і святи́я і блаже́нния жи́зні прича́стници би́ти! Єгда́ же по ді́йству дия́волю, человікоуби́йці іскони́, єди́ном челові́ком гріх в мир вни́де і гріхо́м смерть, тогда́ по неізрече́нному человіколю́бію Твоєму́ Ти опреділи́л єси́ Кресто́м і Воскресе́нієм Свої́м свободи́ти согреши́вшия лю́ди Твої́ от про́пасти а́дови і сме́рті ві́чния. І єгда́ при́йде ісполне́ніє време́н, Ти снисше́л єси́ во днех пло́ті Своєя́, я́ко Па́стир До́брий, на взиска́ніє заблу́дших ове́ць Твої́х, і пре́жде Креста́ Своєго́ і во́льния стра́сті во Вифа́нію прише́д, Ти єди́ним сло́вом Ла́заря, дру́га Твоєго́, уме́рша і погребе́нна, воззва́в от а́да, із ме́ртвих воскреси́л єси́. І та́ко ве́ліїм сим і стра́шним чу́дом пре́жде живоно́сния сме́рті Твоєя́ сме́ртную держа́ву потря́сл єси́, предвозвіща́я четверодне́внаго возста́нієм ско́роє Твоє́, Живода́вче Христе́, тридне́вноє із ме́ртвих Воскресе́ніє, нас всіх уві́рил єси́, я́ко хо́щеши темнообра́зноє а́дськоє ца́рство крі́постію Своє́ю сокруши́ти і о́бщеє Воскресе́ніє всіх яви́ти, показу́я Ла́заря, я́ко пакибитія́ на́шего преднача́тіє спаси́тельноє. Сего́ ра́ди і ми недосто́йнії с Ма́рфою і Марі́єю ни́ні да лику́єм сві́тло і с Вифа́нієй да торжеству́єм, безмі́рноє Твоє́ снисхожде́ніє ни́ні пра́зднующе і прослезе́нієм Твої́м над Ла́зарем бу́дущеє утоле́ніє слез і сме́рті умерщвле́ніє ра́достно предначина́юще. Сподо́би же і всім нам душа́ми чи́стими і нескве́рними уми́, кро́тким же се́рдцем і смире́нним нра́вом, с Вифа́нією Тебі́, кро́ткаго Влади́ку, прия́ти, і лука́ваго горди́ню сокруши́ти, і отве́рсти вхо́ди серде́ць на́ших, да с ві́рою, я́коже Марі́я, пома́жем ми́ром любве́ пречи́стії но́зі Твої́, і со всеусе́рдієм мно́гим, я́ко же Ма́рфа, послу́жим Тебі́, вкуша́юще Пречи́стоє Ті́ло і Са́мую Честну́ю Кров Твою́ на та́їнственной Ве́чері Твоє́й, на не́йже обля́зі с на́ми і істочи́ нам многоці́нноє моли́тви ми́ро, і сле́зи покая́нія, і благоуха́ніє цілому́дрія і чистоти́, да та́ко благоукраше́ннії і просвіще́ннії, усли́шим глаше́ніє Твоє́: “Се стою́ при две́ріх і толку́”, і по гла́су Твоєму́ да отве́рзем две́рі се́рдця і оби́тель сотвори́м Тебі́, ви́ну служа́ще Тебі́ і прославля́юще Тя со Безнача́льним Твої́м Отце́м і Пресвяти́м і Благи́м і Животворя́щим Твої́м Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва святому праведному Лазарю","ps":["О, зіло́ преди́вний і ізря́дний дру́же Христо́в Святи́й Пра́ведний Ла́зарю, Вифа́нії похвало́ і всей вселе́нній превели́коє удивле́ніє! Благослове́н дом твой, єго́же Госпо́дь наш Ісу́с Христо́с во днех пло́ті Своєя́ с любо́вію посеща́ше, ви́дя ві́ру і добро́ту душі́ твоєя́ і боголюби́вих сесте́р твої́х Ма́рфи і Марі́ї, зане́ ти возлюби́л єси́ Єго́ всім се́рдцем твої́м, все́ю душе́ю твоє́ю, все́ю ми́слію твоє́ю і Тім до конця́ возлю́блен бил єси́. Ди́вни та́йни твоя́, на тебі́ Боже́ственним Дру́гом Твої́м і Го́сподом на́шим явле́нния, я́ко ізво́лися Єму́ пре́жде Креста́ Своєго́ і Воскресе́нія показа́ти на тебі́ всему́ ми́ру Сла́ву Свою́ і сотвори́ти тя предвозве́стника пресві́тлаго Своєго́ із ме́ртвих тридне́внаго Воскресе́нія. Сего́ ра́ди Той, я́ко Влади́ка живота́ і сме́рті, попусти́ тебі́ сме́ртним сном усну́ти, і погребе́ну би́ти, і да́же до а́дових глуби́н сни́ти, іді́же ти узрі́л єси́ су́щия от ві́ка уме́ршия во мно́жестві неісче́тном а́довими у́зами содержи́мия, і стра́шниє стра́хи ви́діл єси́. І та́мо, єгда́ ті́ло твоє́ возсмерде́нію сме́ртному уже́ предаде́ся, по чети́ріх днех ти усли́шал єси́ Боже́ственний глас Дру́га твоєго́, на гроб твой прише́дшаго: “Ла́заре, гряди́ вон!” І по гла́су сему́ ти а́біє із гро́ба возста́л єси́ і та́ко Вифа́нію возвесели́л єси́ і Ма́рфини і Марі́їни сле́зи утоли́л єси́, фарисе́ї же і кни́жники, в ожесточе́нії серде́ць су́щих устраши́л єси́. Утоли́ же, святи́й дру́же Христо́в, і на́ші сле́зи, гріх ра́ди на́ших пролива́ємії, оживотвори́ на́ші ду́ші і тілеса́, во возсмерде́нії страсте́й і нечисто́т гріхо́вних су́щії, воздви́гни нас із гро́ба отча́янія і лю́таго уни́нія, всіх же нас ізба́ви от ві́чния сме́рти, я́коже і тебі́ Госпо́дь наш возста́ви от успе́нія сме́ртнаго. І умоли́ ми́лостиваго Бо́га, да сподо́бит нас прича́стници би́ти ві́чния жи́зні, є́юже і ти по труді́х святи́тельства на о́строві Ки́прстем сам ни́ні наслажда́єшися во оби́теліх ра́йських, прославля́юще Всесвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Живоно́сниє глаго́ли Спа́са в се́рдці своє́м прия́л єси́ / і глас повелі́нія Зижди́телева в преіспо́дніх усли́ша, / теки́й воста́ше с пелена́ми, показу́я держа́ву Христо́ву / і по́сліжде пропові́дуя в язи́ціх Того́ сла́вноє Воскресе́ніє, / Ла́заре дру́же Госпо́день досточу́дне, / моли́, Єго́же возлюби́л єси́, // поми́ловати душі́ на́ша."]}],"notes":[]}];
export default D;
